# # # # # # =============================================================================
# # # # # # TYPE=MATCH — IMPROVED DEDICATED PARSER
# # # # # # =============================================================================
# # # # # # Supported left-side identifier families:
# # # # # #   Latin caps:   A B C D
# # # # # #   Hindi:        अ ब स द
# # # # # #   Latin roman:  i ii iii iv  (lower)
# # # # # #   Latin roman:  I II III IV  (upper)
# # # # # #   Digits:       1 2 3 4
# # # # # #
# # # # # # Supported separators for INLINE layout:
# # # # # #   -    --    |    –   (en-dash)   —   (em-dash)
# # # # # #
# # # # # # Two layout modes detected automatically:
# # # # # #   INLINE:    (A) -- (i)    per line
# # # # # #   DUAL-LIST: सूची I: + सूची II:  (or सूची-I / सूची-II headings)

# # # # # # Regex atoms
# # # # # _LATIN_CAPS_RE   = re.compile(r'^[A-D]$', re.IGNORECASE)
# # # # # _HINDI_ALPHA_RE  = re.compile(r'^[अबसद]$')
# # # # # _ROMAN_RE        = re.compile(r'^(?:i{1,4}|iv|vi{0,3}|ix|xi{0,2}|I{1,4}|IV|VI{0,3}|IX|XI{0,2})$')
# # # # # _DIGIT_RE        = re.compile(r'^[1-4]$')

# # # # # # Inline match row: (KEY) SEP (KEY)  — both sides must have a parenthesised key
# # # # # _INLINE_MATCH_RE = re.compile(
# # # # #     r'^\s*'
# # # # #     r'\(\s*([A-Da-dअबसद]|[ivxIVX]{1,4}|[1-4])\s*\)'   # left key
# # # # #     r'(?:[^()\n]*?)'                                     # optional label text on left side
# # # # #     r'\s*(?:--|[|–—-])\s*'                               # separator
# # # # #     r'\(\s*([A-Da-dअबसद]|[ivxIVX]{1,4}|[1-4])\s*\)'   # right key
# # # # #     r'(?:[^()\n]*)?\s*$',
# # # # #     re.IGNORECASE
# # # # # )

# # # # # # Enumeration item: (KEY) text  — used for dual-list extraction
# # # # # _ENUM_ITEM_RE = re.compile(
# # # # #     r'^\s*\(\s*([A-Da-dअबसद]|[ivxIVX]{1,4}|[1-4])\s*\)\s*(.+)$',
# # # # #     re.IGNORECASE
# # # # # )

# # # # # # MCQ option: (a)/(b)/(c)/(d) — used to detect where options section starts
# # # # # _MCQ_OPT_RE = re.compile(r'^\s*\(\s*([a-dA-D])\s*\)')

# # # # # # Heading markers for dual-list
# # # # # _SUCHI_I_RE  = re.compile(r'सूची\s*[-–]?\s*I(?!\s*I)', re.IGNORECASE)
# # # # # _SUCHI_II_RE = re.compile(r'सूची\s*[-–]?\s*II',        re.IGNORECASE)


